questionvariables.text:
wordlength1:rand([6,7,8]);
word:if wordlength1 = 6 then rand(["AMOEBA", "ATHENA"]) elseif wordlength1=7 then rand(["ALGEBRA","ALBERTA","AGNOSIA"]) else "ANGELICA";
word1:if wordlength1=6  then "four" elseif wordlength1=7 then "five" else "six";
ta:if wordlength1=6 then factorial(4)/factorial(2) elseif wordlength1 =7 then factorial(5)/factorial(2) else factorial(6)/factorial(2);
